class Solution {
public:
    int minTimeToReach(vector<vector<int>>& moveTime) {
        int n = moveTime.size();
        int m = moveTime[0].size();
        vector<vector<vector<int>>> dist(n, vector<vector<int>>(m, vector<int>(2, 1e9 + 7)));
        dist[0][0][0] = 0;

        using State = tuple<int, int, int, int>;
        priority_queue<State, vector<State>, greater<State>> pq;
        pq.push({0, 0, 0, 0});

        int dirs[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        while (!pq.empty()) {
            auto [t, r, c, p] = pq.top();
            pq.pop();
            if (r == n - 1 && c == m - 1) return t;
            if (t > dist[r][c][p]) continue;

            int cost = (p == 0 ? 1 : 2);
            int np = 1 - p;
            for (auto& d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < n && nc >= 0 && nc < m) {
                    int nt = max(t, moveTime[nr][nc]) + cost;
                    if (nt < dist[nr][nc][np]) {
                        dist[nr][nc][np] = nt;
                        pq.push({nt, nr, nc, np});
                    }
                }
            }
        }
        return -1;
    }
};

class Solution {
    public int minTimeToReach(int[][] moveTime) {
        int n = moveTime.length;
        int m = moveTime[0].length;
        int[][][] dist = new int[n][m][2];
        for (int[][] mat : dist) {
            for (int[] row : mat) Arrays.fill(row, Integer.MAX_VALUE);
        }
        dist[0][0][0] = 0;

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
        pq.offer(new int[]{0, 0, 0, 0});

        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        while (!pq.isEmpty()) {
            int[] curr = pq.poll();
            int t = curr[0], r = curr[1], c = curr[2], p = curr[3];
            if (r == n - 1 && c == m - 1) return t;
            if (t > dist[r][c][p]) continue;

            int cost = (p == 0 ? 1 : 2);
            int np = 1 - p;
            for (int[] d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < n && nc >= 0 && nc < m) {
                    int nt = Math.max(t, moveTime[nr][nc]) + cost;
                    if (nt < dist[nr][nc][np]) {
                        dist[nr][nc][np] = nt;
                        pq.offer(new int[]{nt, nr, nc, np});
                    }
                }
            }
        }
        return -1;
    }
}

var minTimeToReach = function(moveTime) {
    const n = moveTime.length;
    const m = moveTime[0].length;
    const dist = Array.from({ length: n }, () => 
        Array.from({ length: m }, () => [Infinity, Infinity])
    );
    dist[0][0][0] = 0;

    const pq = [[0, 0, 0, 0]];
    const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];

    while (pq.length > 0) {
        let minIdx = 0;
        for (let i = 1; i < pq.length; i++) {
            if (pq[i][0] < pq[minIdx][0]) minIdx = i;
        }
        const [t, r, c, p] = pq.splice(minIdx, 1)[0];

        if (r === n - 1 && c === m - 1) return t;
        if (t > dist[r][c][p]) continue;

        const cost = (p === 0 ? 1 : 2);
        const np = 1 - p;
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < n && nc >= 0 && nc < m) {
                const nt = Math.max(t, moveTime[nr][nc]) + cost;
                if (nt < dist[nr][nc][np]) {
                    dist[nr][nc][np] = nt;
                    pq.push([nt, nr, nc, np]);
                }
            }
        }
    }
    return -1;
};
